  // ═══ Scanner d'EAN ═══════════════════════════════════════════════════
  var _scan = null;            // { stream, video, ov, reader, raf, busy, last, n, found, hl, tries }
  var _eanMap = {};            // { enseigne: { eanNormalisé: cléProduit } } — rapprochements mémorisés
