    if (typeof ZXingWASM !== 'undefined') go();
    else if (typeof lazyLoad === 'function') lazyLoad(LIB_ZXW, go, function(){ if (_scan) { scanStatus('Lecteur avancé non chargé : lecteur de secours'); legacyStart(); } });
